import os, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        print("No RLM_SESSION_DIR")
        return {}
    # Load session file from current instance's conversation
    conv_dir = os.path.dirname(d)
    sessions_file = os.path.join(conv_dir, '..', 'sessions', os.path.basename(d) + '.jsonl')
    sessions_file = os.path.normpath(sessions_file)
    try:
        with open(sessions_file, 'r') as f:
            content = f.read()
    except Exception as e:
        print(f"Error reading sessions file: {e}")
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ input|Demo pair \d+ output|Test input)\s*\((\d+)x(\d+)\):\s*(.*)$', content, re.MULTILINE):
        k, h, w, rest = m.groups()
        rows = []
        lines = rest.strip().split('\n')[:int(h)]
        for r in lines:
            rows.append([int(x) for x in r.split()])

        prefix = "output" if "output" in k else ("input" if "input" in k else "test")
        G[k] = {'type': prefix, 'rows': rows}

    return G

G = load_grids()
