def transform(grid):
    result = [[0]*len(row) for row in grid]

    # Copy 0s (and potentially other non-2, non-3 values)
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            val = grid[r][c]
            if val == 0:
                result[r][c] = 0

    # Transform 2 -> 8 if position matches pattern
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 2:
                if r % 12 == 0 or c % 6 == 0:
                    result[r][c] = 8
                else:
                    result[r][c] = 2

    # Transform 3 -> 0
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] == 3:
                result[r][c] = 0

    return result

